/// Case-insensitive (already-lowercased) id lookup for the CSV roster's
/// blocks; `BlockType::from_name` adds "mud"/"redstone"/"crystal" on top
/// for the non-CSV extras.
pub(crate) fn csv_from_name(lower_name: &str) -> Option<BlockType> {
    Some(match lower_name {
        "grass" => BlockType::Grass,
        "sand" => BlockType::Sand,
        "spruce_wood" => BlockType::SpruceWood,
        "stone" => BlockType::Stone,
        "water" => BlockType::Water,
        "oak_leaves" => BlockType::OakLeaves,
        "soil" => BlockType::Soil,
        "bedrock" => BlockType::Bedrock,
        "cobblestone" => BlockType::Cobblestone,
        "basalt" => BlockType::Basalt,
        "cherry_wood" => BlockType::CherryWood,
        "cherry_leaves" => BlockType::CherryLeaves,
        "birch_wood" => BlockType::BirchWood,
        "birch_leaves" => BlockType::BirchLeaves,
        "gold_ore" => BlockType::GoldOre,
        "diamond_ore" => BlockType::DiamondOre,
        "emerald_ore" => BlockType::EmeraldOre,
        "copper_ore" => BlockType::CopperOre,
        "oak_wood" => BlockType::OakWood,
        "spruce_leaves" => BlockType::SpruceLeaves,
        "pumpkin" => BlockType::Pumpkin,
        "bricks" => BlockType::Bricks,
        "short_grass" => BlockType::ShortGrass,
        _ => return None,
    })
}
